host='10.96.27.109'; port=2638; user='wangchong'; pwd='123456'; base='/home/wangchong/data/fwz'
GROUPS={'AD':{'out':f'{base}/adni-ad-data','cat':f'{base}/adni-ad-categorized'},'CN':{'out':f'{base}/adni-cn-data','cat':f'{base}/adni-cn-categorized'}}
BOUNDS=[('01_半年以内',0,274),('02_一年',274,548),('03_一年半',548,730),('04_两年以上',730,99999)]
labels={'01_半年以内':'< 9 个月','02_一年':'9-18 个月','03_一年半':'18-24 个月','04_两年以上':'>= 24 个月'}
cli=paramiko.SSHClient(); cli.set_missing_host_key_policy(paramiko.AutoAddPolicy()); cli.connect(host,port=port,username=user,password=pwd,timeout=20)

def ex(cmd):
 i,o,e=cli.exec_command(cmd,timeout=120); out=o.read().decode(errors='ignore').strip(); err=e.read().decode(errors='ignore').strip(); return out,err

for g,p in GROUPS.items():
 out_root=p['out']; cat_root=p['cat']
 out,err=ex(f'find {out_root} -name t1w_final.nii.gz -printf "%P\\n" | sort')
 if err: print(f'[{g}] find err: {err}')
 subject_dates=defaultdict(list)
 for line in [x for x in out.splitlines() if x.strip()]:
  parts=line.split('/')
  if len(parts)>=3:
   subj,date_str=parts[0],parts[1]
   try: subject_dates[subj].append(datetime.strptime(date_str,'%Y-%m-%d').date())
   except: pass
 multi={s:sorted(ds) for s,ds in subject_dates.items() if len(ds)>=2}
 ex(f'mkdir -p {cat_root}')
 for name,_,_ in BOUNDS: ex(f'mkdir -p "{cat_root}/{name}"')
 counts={name:0 for name,_,_ in BOUNDS}
 for subj,dates in multi.items():
  span=(dates[-1]-dates[0]).days
  for name,lo,hi in BOUNDS:
   if lo<=span<hi:
    ex(f'ln -sfn "{out_root}/{subj}" "{cat_root}/{name}/{subj}"'); counts[name]+=1; break
 readme=['# ADNI '+g+' 纵向数据 - 按随访时间跨度分类\n',f'原始处理数据: `{out_root}`\n','| 文件夹 | 标准 | 受试者数 |','|--------|------|----------|']
 for name,_,_ in BOUNDS: readme.append(f'| `{name}` | {labels[name]} | {counts[name]} |')
 readme.append(f'\n生成时间: {datetime.now().strftime("%Y-%m-%d %H:%M")}')
 text='\n'.join(readme)
 ex(f"cat > {cat_root}/README.md << 'HEREDOC'\n{text}\nHEREDOC")
 print(f'[{g}] processed_subjects={len(subject_dates)}, multi={len(multi)}, counts={counts}')

for g,p in GROUPS.items():
 print('---',g,'---')
 for name,_,_ in BOUNDS:
  out,_=ex(f'ls -1 "{p["cat"]}/{name}" 2>/dev/null | wc -l'); print(name, out.strip())
cli.close()"

