from collections import defaultdict

import paramiko

HOST = "10.96.27.109"
PORT = 2638
USER = "wangchong"
PASSWORD = "123456"
BASE = "/home/wangchong/data/fwz"

GROUPS = {
    "AD": {
        "out": f"{BASE}/adni-ad-data",
        "cat": f"{BASE}/adni-ad-categorized",
    },
    "CN": {
        "out": f"{BASE}/adni-cn-data",
        "cat": f"{BASE}/adni-cn-categorized",
    },
}

BOUNDS = [
    ("01_半年以内", 0, 274),
    ("02_一年", 274, 548),
    ("03_一年半", 548, 730),
    ("04_两年以上", 730, 99999),
]

LABELS = {
    "01_半年以内": "< 9 个月",
    "02_一年": "9-18 个月",
    "03_一年半": "18-24 个月",
    "04_两年以上": ">= 24 个月",
}


def ssh_exec(client: paramiko.SSHClient, cmd: str, timeout: int = 120):
    _, stdout, stderr = client.exec_command(cmd, timeout=timeout)
    out = stdout.read().decode(errors="ignore").strip()
    err = stderr.read().decode(errors="ignore").strip()
    return out, err


def rebuild_group(client: paramiko.SSHClient, group: str, out_root: str, cat_root: str):
    out, err = ssh_exec(client, f'find {out_root} -name "t1w_final.nii.gz" -printf "%P\\n" | sort')
    if err:
        print(f"[{group}] find warning: {err}")

    subject_dates = defaultdict(list)
    for line in [x for x in out.splitlines() if x.strip()]:
        parts = line.split("/")
        if len(parts) >= 3:
            subj, date_str = parts[0], parts[1]
            try:
                subject_dates[subj].append(datetime.strptime(date_str, "%Y-%m-%d").date())
            except ValueError:
                pass

    multi = {s: sorted(ds) for s, ds in subject_dates.items() if len(ds) >= 2}

    ssh_exec(client, f"mkdir -p {cat_root}")
    for name, _, _ in BOUNDS:
        ssh_exec(client, f'mkdir -p "{cat_root}/{name}"')

    counts = {name: 0 for name, _, _ in BOUNDS}
    for subj, dates in multi.items():
        span = (dates[-1] - dates[0]).days
        for name, lo, hi in BOUNDS:
            if lo <= span < hi:
                src = f"{out_root}/{subj}"
                dst = f"{cat_root}/{name}/{subj}"
                ssh_exec(client, f'ln -sfn "{src}" "{dst}"')
                counts[name] += 1
                break

    readme = [
        f"# ADNI {group} 纵向数据 - 按随访时间跨度分类\n",
        f"原始处理数据: `{out_root}`\n",
        "| 文件夹 | 标准 | 受试者数 |",
        "|--------|------|----------|",
    ]
    for name, _, _ in BOUNDS:
        readme.append(f"| `{name}` | {LABELS[name]} | {counts[name]} |")
    readme.append(f"\n生成时间: {datetime.now().strftime('%Y-%m-%d %H:%M')}")
    readme_text = "\n".join(readme)
    ssh_exec(client, f"cat > {cat_root}/README.md << 'HEREDOC'\n{readme_text}\nHEREDOC")

    print(f"[{group}] processed_subjects={len(subject_dates)}, multi={len(multi)}, counts={counts}")

    for name, _, _ in BOUNDS:
        n, _ = ssh_exec(client, f'ls -1 "{cat_root}/{name}" 2>/dev/null | wc -l')
        print(f"  {name}: {n.strip()}")


def main():
    client = paramiko.SSHClient()
    client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
    client.connect(HOST, port=PORT, username=USER, password=PASSWORD, timeout=20)
    try:
        for group, paths in GROUPS.items():
            rebuild_group(client, group, paths["out"], paths["cat"])
    finally:
        client.close()


if __name__ == "__main__":
    main()
